package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

/** Actual explicit native writer with TRUST; mandatory family and legacy gates, no proxy. */
final class ContextTrustedNativeWriterMatrix {
    static int checks;static final int WORK=64000000;static final String RULE="!@u q(u)->r(u);";
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static ContextNativeCandidateInspection.Limits limits(int work,int audit,int capacity){return new ContextNativeCandidateInspection.Limits(1000,8,16,WORK,500000,work,audit,capacity);}
    static void setup(Path dir)throws Exception{ContextNativeCandidateLeaseMatrix.create(dir,"TR","!@u p(u)->q(u);");ContextNativeCandidateLeaseMatrix.create(dir,"TF","!p(1);");ContextNativeCandidateLeaseMatrix.create(dir,"N","!~r(1);");}
    static void connect(ContextNativeCandidateLeaseMatrix.Fixture f,boolean reverse)throws Exception{f.db.connectContext(reverse?"TF":"TR","own");f.db.connectContext(reverse?"TR":"TF","own");f.db.connectContext("N");f.db.saveConnections(f.mind);}
    static boolean write(ContextNativeCandidateLeaseMatrix.Fixture f,String text,ContextNativeCandidateInspection.Limits l,int work,int audit)throws Exception{return f.db.writeNativeProductionCandidate(f.mind,text,l,work,audit,1000000,false);}
    static ContextNativeCommitException nativeRefusal(ContextNativeCandidateLeaseMatrix.Fixture f,String text,ContextNativeCandidateInspection.Limits l,int work,int audit,StorageLifecycleErrorCode code)throws Exception{ContextNativeCommitException e=null;try{write(f,text,l,work,audit);}catch(ContextNativeCommitException expected){e=expected;}require(e!=null&&e.getErrorCode()==code,"actual trusted writer typed native refusal");return e;}
    static void positive()throws Exception{
        Path dir=Files.createTempDirectory("trusted-native-writer-");System.setProperty("user.home",dir.toString());setup(dir);
        for(boolean reverse:new boolean[]{false,true}){String name="X"+reverse;long durable;Map<UUID,Long> pins=new HashMap<>();
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.mind.compile("!anchor(1);",null,false),"actual trusted writer parent");connect(f,reverse);long before=f.db.getRevision();Set<String> original=ContextNativeCommitGuardMatrix.primary(f);for(ContextConnection c:f.db.dmzTopology())pins.put(c.getTarget().getContextId(),c.getTarget().getRevision());
                ContextNativeCommitException conflict=nativeRefusal(f,RULE,limits(WORK,WORK,1),WORK,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(conflict.getNativeEvidence()!=null&&conflict.getCollisions().isEmpty(),"native trusted proof stays distinct from old FamilyAudit collision witnesses");for(ContextNativeBranchInspection.Opposition o:conflict.getNativeEvidence().getOppositions())require(o.sources.size()==4&&o.sources.stream().filter(s->!s.localX).map(s->s.context).distinct().count()==3&&o.sources.stream().filter(s->!s.localX).allMatch(s->pins.get(s.context)==s.revision),"actual pending X plus BOTH trusted originals and independent negative exact pins");conflict.getNativeEvidence().check(WORK,1);require(true,"trusted native sealed evidence independently replays after actual rollback");require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"trusted refutation atomically refuses actual publication");
                f.db.applyConnectionCommand(f.mind,"TF","-p(1);");f.db.applyConnectionCommand(f.mind,"TF","!p(2);");f.db.saveConnections(f.mind);long initialized=f.db.getRevision();ContextNativeCommitException limited=nativeRefusal(f,RULE,limits(WORK,WORK,4096),1,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(limited.getPhase().equals("full-family-qualification")&&limited.getNativeEvidence()==null,"trusted scoped-ready MUST still pass complete-family eligibility");require(f.db.getRevision()==initialized&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"bounded full-family refusal cannot publish even native-stable trusted candidate");
                require(write(f,RULE,limits(WORK,WORK,4096),WORK,WORK),"actual trusted original rule publishes ONLY after native/full-family/legacy gates");require(f.db.getRevision()>initialized&&ContextNativeCommitGuardMatrix.primary(f).size()==2&&ContextNativeCommitGuardMatrix.primary(f).contains(RULE),"trusted writer publishes only original assertion plus anchor, no foreign runtime facts");require(f.user.getData()==f.db&&f.user.getCurrentMind()==f.mind,"actual provider/user remain unchanged without QA proxy");for(ContextConnection c:f.db.dmzTopology())require(pins.get(c.getTarget().getContextId())==c.getTarget().getRevision(),"publication retains exact original physical foreign pins");durable=f.db.getRevision();
            }
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.db.getRevision()>=durable&&ContextNativeCommitGuardMatrix.primary(f).size()==2&&ContextNativeCommitGuardMatrix.primary(f).contains(RULE),"trusted publication durably reopens with original assertions");require(f.db.dmzTopology().size()==3&&f.db.dmzTopology().stream().filter(c->"own".equals(c.getTrustGroup())).count()==2&&f.db.dmzTopology().stream().anyMatch(c->c.getInitialization().size()==2),"durable full trusted group plus independent member and private initialization");for(ContextConnection c:f.db.dmzTopology())require(pins.get(c.getTarget().getContextId())==c.getTarget().getRevision(),"reopen retains exact original member pins");}
        }
        System.out.println("TRUSTED_NATIVE_WRITER_POSITIVE orders=2 typedExactSources=true independentRefusalReplay=true mandatoryFullFamily=true actualPublication=true durablePrivateGroup=true noProxy=true");
    }
    static void refusals()throws Exception{
        Path dir=Files.createTempDirectory("trusted-native-stops-");System.setProperty("user.home",dir.toString());setup(dir);
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"X")){require(f.mind.compile("!anchor(1);",null,false),"trusted refusal parent");connect(f,false);long revision=f.db.getRevision();Set<String> original=ContextNativeCommitGuardMatrix.primary(f);
            ContextNativeCommitException unverified=nativeRefusal(f,RULE,limits(WORK,1,4096),WORK,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(unverified.getPhase().equals("refutation-audit")&&unverified.getNativeEvidence()==null,"unverified actual trusted contradiction has no conflict evidence");ContextNativeCommitException bounded=nativeRefusal(f,RULE,limits(1,WORK,4096),WORK,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);require(bounded.getNativeEvidence()==null,"trusted native work stop cannot export proof prefix");
            ContextNativeCommitException proved=nativeRefusal(f,RULE,limits(WORK,WORK,4096),1,1,StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT);require(proved.getNativeEvidence()!=null,"verified native trusted refutation precedes resource-limited full-family phase");
            nativeRefusal(f,"!@u @v @w edge(u,v)&&edge(v,w)->path(u,w);",limits(WORK,WORK,4096),WORK,WORK,StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE);
            f.db.applyConnectionCommand(f.mind,"TF","-p(1);");f.db.applyConnectionCommand(f.mind,"TF","!p(2);");ContextProductionCommitException fullAudit=null;try{write(f,RULE,limits(WORK,WORK,4096),WORK,1);}catch(ContextProductionCommitException e){fullAudit=e;}require(fullAudit!=null&&fullAudit.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_INCOMPLETE,"old complete-family audit remains mandatory and keeps original error/evidence type on TRUST");require(f.db.getRevision()==revision&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"all trusted bounded/unsupported/audit refusals preserve physical parent");require(write(f,"!afterStops(7);",limits(WORK,WORK,4096),WORK,WORK),"all trusted refusal paths release attempt selection for a fresh qualified write");require(ContextNativeCommitGuardMatrix.primary(f).size()==2,"only original successful post-refusal assertion published");
        }
        System.out.println("TRUSTED_NATIVE_WRITER_REFUSALS nativeWorkAudit=true proofBeforeFamily=true unsupportedFailClosed=true oldFullFamilyAudit=true atomic=true freshAttemptRecovery=true");
    }
}
